def strip(items):
    return '<div style="display: flex; padding: 16px 24px; gap: 0; border-bottom: 1px solid var(--line)">' + ''.join(f'<div style="flex: 1; padding: 0 20px; {"border-left: 1px solid var(--line)" if i else "padding-left: 0"}"><span style="font-size: 12px; color: var(--mut)">{l}</span><div style="display: flex; align-items: baseline; gap: 8px; margin-top: 2px"><span style="font-family: \'Inter Tight\', sans-serif; font-size: 24px; letter-spacing: -0.02em">{v}</span><span style="font-size: 12px; color: {c}">{d}</span></div></div>' for i, (l, v, d, c) in enumerate(items)) + '</div>'
def spark(pts, col='#3B6CF6', w=90, h=28):
    mx, mn = max(pts), min(pts)
    p = ' '.join(f'{"M" if i == 0 else "L"}{i * w / (len(pts) - 1):.1f} {h - 2 - (v - mn) / (mx - mn or 1) * (h - 4):.1f}' for i, v in enumerate(pts))
    return f'<svg width="{w}" height="{h}" viewBox="0 0 {w} {h}" aria-hidden="true"><path d="{p}" fill="none" stroke="{col}" stroke-width="1.8" stroke-linecap="round"></path></svg>'
def listhead(title, icons):
    return f'<div style="height: 60px; flex: none; display: flex; align-items: center; gap: 4px; padding: 0 12px 0 20px"><h1 style="margin: 0; flex: 1; font-size: 18px; font-weight: 600">{title}</h1>{icons}</div>'
def subhead(left, right):
    return f'<div style="height: 60px; flex: none; display: flex; align-items: center; gap: 10px; padding: 0 16px 0 24px; border-bottom: 1px solid var(--line)"><span style="flex: 1; min-width: 0; display: flex; align-items: center; gap: 12px">{left}</span>{right}{SEP}{BELL}</div>'
ACC = '<span style="position: absolute; left: 0; top: 14px; bottom: 14px; width: 3px; border-radius: 0 3px 3px 0; background: var(--warn)"></span>'

