# ======================================================== REPORTS
def reports():
    k = [('Conversations', '1,284', '+12%', [40, 44, 41, 50, 55, 52, 60, 63, 61, 70]), ('Bookings', '312', '+9%', [20, 22, 21, 25, 24, 28, 27, 30, 31, 33]),
         ('Revenue', '₹3,74,400', '+14%', [30, 32, 36, 34, 40, 42, 41, 46, 48, 52]), ('Answered in 10 sec', '96%', '+3 pts', [88, 90, 91, 90, 93, 94, 93, 95, 96, 96])]
    tiles = ''.join(f'<div class="card" style="padding: 14px 16px; display: flex; justify-content: space-between; align-items: flex-end"><span><span style="font-size: 12px; color: var(--mut)">{l}</span><span style="display: block; font-family: \'Inter Tight\', sans-serif; font-size: 26px; letter-spacing: -0.02em; margin-top: 2px">{v}</span><span style="font-size: 12px; color: var(--good)">{d} vs last month</span></span>{spark(p)}</div>' for l, v, d, p in k)
    pts = [30, 34, 28, 40, 46, 38, 52, 49, 55, 61, 58, 64, 70, 66, 72, 78, 74, 80, 77, 85, 90, 84, 88, 95, 92, 98, 96, 104, 101, 110]
    prev = [p * .86 + 4 * math.sin(i) for i, p in enumerate(pts)]
    W, Hh = 620, 170
    mk = lambda arr: ' '.join(f'{"M" if i == 0 else "L"}{i * W / (len(arr) - 1):.1f} {Hh - v * 1.4:.1f}' for i, v in enumerate(arr))
    line = f'<svg viewBox="0 0 {W} {Hh}" width="100%" height="{Hh}" aria-label="Bookings per day (sample)">{"".join(f"<line x1=\'0\' x2=\'{W}\' y1=\'{y}\' y2=\'{y}\' stroke=\'var(--line)\'></line>" for y in (40, 85, 130))}<path d="{mk(prev)}" fill="none" stroke="var(--mut2)" stroke-width="1.6" stroke-dasharray="4 4"></path><path d="{mk(pts)}" fill="none" stroke="#3B6CF6" stroke-width="2.4"></path></svg>'
    days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']; hrs = list(range(8, 22, 2))
    def heat(d, h):
        base = {'Sat': 1.0, 'Fri': .85, 'Sun': .55}.get(d, .6)
        peak = math.exp(-((h - 19) ** 2) / 10) + .6 * math.exp(-((h - 11) ** 2) / 6)
        return min(1, base * peak + (.4 if d == 'Sat' and h < 14 else 0))
    hm = '<div style="display: grid; grid-template-columns: 34px repeat(7, 1fr); gap: 3px; font-size: 11px; color: var(--mut2)"><span></span>' + ''.join(f'<span style="text-align: center">{h if h <= 12 else h - 12}{"a" if h < 12 else "p"}</span>' for h in hrs)
    for d in days:
        hm += f'<span style="line-height: 22px">{d}</span>' + ''.join(f'<span style="height: 22px; border-radius: 5px; background: rgba(59,108,246,{.08 + .85 * heat(d, h):.2f})"></span>' for h in hrs)
    hm += '</div>'
    ch = [('WhatsApp', 58, WA), ('Phone', 21, PH), ('Instagram', 11, IG), ('Website', 7, GLOBE), ('Google', 3, GO)]
    chb = ''.join(f'<div style="display: flex; align-items: center; gap: 10px; font-size: 13px"><span style="width: 100px; display: flex; gap: 8px; align-items: center; color: var(--mut)">{f(13)}{n}</span><span style="flex: 1; height: 8px; border-radius: 4px; background: var(--soft)"><span style="display: block; width: {p}%; height: 100%; border-radius: 4px; background: var(--ink)"></span></span><span style="width: 34px; text-align: right">{p}%</span></div>' for n, p, f in ch)
    main = f'''<div style="flex: 1; min-width: 0; display: flex; flex-direction: column">{phead("Reports", "Last 30 days", '<span class="seg"><label>7 days</label><label style="background: var(--pop); color: var(--text); box-shadow: 0 1px 2px rgba(0,0,0,.12)">30 days</label><label>90 days</label></span>' + ob("All locations") + ob("Download", "download"))}
      <div style="flex: 1; overflow: hidden; padding: 20px 24px; display: flex; flex-direction: column; gap: 14px">
        <p style="margin: 0; font-size: 15px; line-height: 1.55; color: var(--text)">A strong month. <b style="font-weight: 600">312 bookings</b>, up 9%. Vegham answered <b style="font-weight: 600">96%</b> of messages within 10 seconds and saved <b style="font-weight: 600">41 missed calls</b>. Saturday mornings and weekday evenings are your busiest times.</p>
        <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px">{tiles}</div>
        <div style="display: grid; grid-template-columns: 1.55fr 1fr; gap: 14px">
          <div class="card" style="padding: 16px 20px"><div style="display: flex; justify-content: space-between; align-items: center"><b style="font-weight: 600; font-size: 14.5px">Bookings per day</b><span style="display: flex; gap: 14px; font-size: 12px; color: var(--mut)"><span style="display: inline-flex; align-items: center; gap: 6px"><span style="width: 14px; height: 2px; background: #3B6CF6"></span>This month</span><span style="display: inline-flex; align-items: center; gap: 6px"><span style="width: 14px; height: 0; border-top: 2px dashed var(--mut2)"></span>Last month</span></span></div><div style="margin-top: 10px">{line}</div></div>
          <div class="card" style="padding: 16px 20px"><b style="font-weight: 600; font-size: 14.5px">Busiest times</b><span style="display: block; font-size: 12px; color: var(--mut); margin: 2px 0 10px">Conversations by day and hour</span>{hm}</div></div>
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 14px">
          <div class="card" style="padding: 16px 20px; display: flex; flex-direction: column; gap: 10px"><b style="font-weight: 600; font-size: 14.5px">Where customers came from</b>{chb}</div>
          <div class="card" style="padding: 16px 20px"><b style="font-weight: 600; font-size: 14.5px">Top services</b>{"".join(f'<div style="display: flex; justify-content: space-between; padding: 8px 0; border-top: 1px solid var(--line); font-size: 13px; margin-top: {8 if i == 0 else 0}px"><span>{n} <span style="color: var(--mut2)">· {b}</span></span><b style="font-weight: 500">{r}</b></div>' for i, (n, b, r) in enumerate([("Standard", 148, "₹1,77,600"), ("Monthly package", 19, "₹1,14,000"), ("Group session", 61, "₹73,200"), ("First visit", 54, "₹27,000")]))}</div>
          <div class="card" style="padding: 16px 20px"><b style="font-weight: 600; font-size: 14.5px">Who handled conversations</b><div style="display: flex; align-items: center; gap: 18px; margin-top: 12px"><svg width="96" height="96" viewBox="0 0 42 42" aria-label="83 percent by Vegham"><circle cx="21" cy="21" r="15.9" fill="none" stroke="var(--soft)" stroke-width="5"></circle><circle cx="21" cy="21" r="15.9" fill="none" stroke="var(--ink)" stroke-width="5" stroke-dasharray="83 17" stroke-dashoffset="25"></circle></svg><div style="font-size: 13px; display: flex; flex-direction: column; gap: 6px"><span><b style="font-weight: 600">83%</b> Vegham alone</span><span><b style="font-weight: 600">14%</b> Handed to your team</span><span><b style="font-weight: 600">3%</b> Your team only</span></div></div></div></div></div></div>'''
    return f'<div style="display: flex; height: 100%; position: relative">{main}{smp}</div>'

